// Schema Prisma gerado a partir de "doc_completo" - revise antes de usar em produção.

model Cliente {
  id Int @id
  nome String
  email String? @unique
  idade Int?
  localizacao String?
  area String?
  pedidos Pedido[]
}

model Pedido {
  id BigInt @id
  clienteId Int @map("cliente_id")
  status String?
  total Decimal?
  cliente Cliente @relation(fields: [clienteId], references: [id])
  items Item[]
}

model Item {
  pedidoId BigInt @map("pedido_id")
  numero Int
  produto String?
  pedido Pedido @relation(fields: [pedidoId], references: [id])

  @@id([pedidoId, numero])
}

model LogEvento {
  id Int?
  dia DateTime

  @@id([id, dia])
  @@map("log_evento")
}

model LogEvento2024 {
  @@map("log_evento_2024")
}

model AuditoriaBase {
  id Int @id
  quando DateTime?
  @@map("auditoria_base")
}

model AuditoriaPedido {
  pedidoId Int? @map("pedido_id")
  @@map("auditoria_pedido")
}

